-- WARNING: deletes every itinerary stop of the Malaysia trip departing 2026-11-04 first, including manual edits and done flags.
begin;

delete from public.trip_itinerary_stops
where trip_code = (select code from public.trips
  where country ilike 'malaysia%'
  order by (departure_date = date '2026-11-04') desc nulls last, created_at
  limit 1);

